#include "derelict/DerelictRouteState.hpp"
#include "core/Saturating.hpp"
#include <algorithm>
namespace elysium::derelict {RouteState DerelictRouteAdapter::evaluate(const SectionEnvironmentSnapshot&s,const RouteCapability&c)const{RouteState o{s.sectionStableId,s.revision,true,{}};auto add=[&](RouteBlocker b,CounterVerb v,double sev,bool blocks=true){o.reasons.push_back({b,v,elysium::safe::nonNegative(sev)});if(blocks)o.passable=false;};if(!s.sectionStableId){add(RouteBlocker::Destroyed,CounterVerb::Repair,1);return o;}if(s.destroyed)add(RouteBlocker::Destroyed,CounterVerb::Repair,1);if(s.powerFraction<=0)add(RouteBlocker::Unpowered,CounterVerb::RestorePower,1);if((s.pressureFraction<=0||s.leaking)&&!c.vacuumProtection)add(s.leaking?RouteBlocker::Leak:RouteBlocker::Vacuum,CounterVerb::Seal,1);if(s.gravityFraction<=0&&!c.zeroGMobility)add(RouteBlocker::NoGravity,CounterVerb::UseZeroGMobility,1);if(s.securityLocked&&!c.securityAccess)add(RouteBlocker::SecurityLocked,CounterVerb::BypassSecurity,1);if(s.fireLevel>0&&!c.fireProtection)add(RouteBlocker::Fire,CounterVerb::Extinguish,s.fireLevel);if(s.contaminationLevel>0&&!c.contaminationProtection)add(RouteBlocker::Contamination,CounterVerb::Decontaminate,s.contaminationLevel);std::sort(o.reasons.begin(),o.reasons.end(),[](auto&a,auto&b){return a.blocker<b.blocker;});return o;}
std::vector<PhysicalPersistenceIntent>DerelictRouteAdapter::counterIntents(const RouteState&s)const{std::vector<PhysicalPersistenceIntent>o;for(auto&r:s.reasons)if(r.counter!=CounterVerb::None)o.push_back({s.sectionStableId,r.counter});return o;}
std::vector<SecurityActorRequest>DerelictRouteAdapter::securityRequests(const SectionEnvironmentSnapshot&s)const{return s.securityAwake?std::vector<SecurityActorRequest>{{s.sectionStableId,true}}:std::vector<SecurityActorRequest>{};}
} // namespace elysium::derelict
